+        catch (Exception ex)
+        {
+            _statusMessage = $"Failed to save: {ex.Message}";
+            _isError = true;
+        }
+        finally
+        {
+            _saving = false;
+        }
+    }
+
+    private void DiscardChanges()
+    {
+        if (_profile is not null)
+        {
+            PopulateFields(_profile);
+            _statusMessage = null;
+        }
+    }
+}
