+            <div class="card-header d-flex justify-content-between align-items-center"
+                 role="button" @onclick="() => _passwordPanelOpen = !_passwordPanelOpen">
+                <strong>Change Password</strong>
+                <span class="expand-icon">@(_passwordPanelOpen ? "▲" : "▼")</span>
+            </div>
+            @if (_passwordPanelOpen)
+            {
+                <div class="card-body">
+                    @if (_settings.LastPasswordChange.HasValue)
+                    {
+                        <p class="text-muted small">
+                            Last changed: @_settings.LastPasswordChange.Value.ToString("MMMM dd, yyyy")
+                        </p>
+                    }
+
+                    <div class="mb-3">
+                        <label class="form-label">Current Password</label>
+                        <input type="password" class="form-control" @bind="_currentPassword" />
+                    </div>
+                    <div class="mb-3">
+                        <label class="form-label">New Password</label>
+                        <input type="password" class="form-control" @bind="_newPassword" />
+                    </div>
+                    <div class="mb-3">
+                        <label class="form-label">Confirm New Password</label>
+                        <input type="password" class="form-control" @bind="_confirmPassword" />
+                    </div>
+
+                    @if (_passwordError is not null)
+                    {
+                        <div class="text-danger small mb-2">@_passwordError</div>
+                    }
+
+                    <button class="btn btn-warning" @onclick="ChangePasswordAsync" disabled="@_changingPassword">
+                        @if (_changingPassword)
+                        {
+                            <span class="spinner-border spinner-border-sm me-1" role="status"></span>
+                        }
+                        Update Password
+                    </button>
+                </div>
+            }
+        </div>
+
+        <!-- Two-Factor Authentication -->
+        <div class="card mb-4">
+            <div class="card-body d-flex justify-content-between align-items-center">
+                <div>
+                    <strong>Two-Factor Authentication</strong>
+                    <div class="mt-1">
+                        @if (_twoFactorEnabled)
+                        {
+                            <span class="badge bg-success">Enabled</span>
+                        }
+                        else
+                        {
+                            <span class="badge bg-secondary">Disabled</span>
+                        }
+                    </div>
+                </div>
+                <div class="form-check form-switch">
+                    <input class="form-check-input" type="checkbox" role="switch"
+                           checked="@_twoFactorEnabled"
+                           @onchange="e => _twoFactorEnabled = (bool)e.Value!" />
+                </div>
+            </div>
+        </div>
+
+        <!-- Active Sessions -->
+        <h5>Active Sessions</h5>
+        <div class="table-responsive">
+            <table class="table table-hover">
+                <thead>
+                    <tr>
+                        <th>Device</th>
+                        <th>Location</th>
+                        <th>Last Active</th>
+                        <th></th>
+                    </tr>
+                </thead>
+                <tbody>
+                    @foreach (var session in _sessions)
+                    {
+                        <tr>
+                            <td>
+                                @session.Device
+                                @if (session.Id == "current")
+                                {
+                                    <span class="badge bg-primary ms-1">Current</span>
+                                }
+                            </td>
+                            <td>@session.Location</td>
+                            <td>@FormatLastActive(session.LastActive)</td>
+                            <td>
+                                @if (session.Id != "current")
+                                {
+                                    <button class="btn btn-sm btn-outline-danger"
+                                            @onclick="() => PromptRevoke(session)">
+                                        Revoke
+                                    </button>
+                                }
+                            </td>
+                        </tr>
+                    }
+                </tbody>
+            </table>
+        </div>
+
+        <!-- Revoke Confirmation Dialog -->
+        @if (_sessionToRevoke is not null)
+        {
+            <div class="modal-backdrop fade show"></div>
+            <div class="modal fade show d-block" tabindex="-1" role="dialog">
+                <div class="modal-dialog modal-dialog-centered" role="document">
+                    <div class="modal-content">
+                        <div class="modal-header">
+                            <h5 class="modal-title">Revoke Session</h5>
+                            <button type="button" class="btn-close" @onclick="CancelRevoke"></button>
+                        </div>
+                        <div class="modal-body">
+                            <p>Are you sure you want to revoke the session on <strong>@_sessionToRevoke.Device</strong> in <strong>@_sessionToRevoke.Location</strong>?</p>
+                            <p class="text-muted small">This will sign out the device immediately.</p>
+                        </div>
+                        <div class="modal-footer">
+                            <button class="btn btn-secondary" @onclick="CancelRevoke">Cancel</button>
+                            <button class="btn btn-danger" @onclick="ConfirmRevokeAsync" disabled="@_revoking">
+                                @if (_revoking)
+                                {
+                                    <span class="spinner-border spinner-border-sm me-1" role="status"></span>
+                                }
+                                Revoke Session
+                            </button>
+                        </div>
+                    </div>
+                </div>
+            </div>
+        }
+    }
+</div>
+
+@code {
+    private SecuritySettings? _settings;
+    private List<ActiveSession> _sessions = [];
+    private bool _twoFactorEnabled;
+    private bool _loading = true;
+
+    // Password state
+    private bool _passwordPanelOpen;
+    private string _currentPassword = "";
+    private string _newPassword = "";
+    private string _confirmPassword = "";
+    private string? _passwordError;
+    private bool _changingPassword;
+
+    // Revoke state
+    private ActiveSession? _sessionToRevoke;
+    private bool _revoking;
+
+    // Status
+    private string? _statusMessage;
+    private bool _isError;
+
+    protected override async Task OnInitializedAsync()
+    {
+        _loading = true;
+        _settings = await SettingsService.GetSecuritySettingsAsync();
+        _sessions = [.. _settings.Sessions];
+        _twoFactorEnabled = _settings.TwoFactorEnabled;
+        _loading = false;
+    }
+
+    private async Task ChangePasswordAsync()
+    {
+        _passwordError = null;
+
+        if (string.IsNullOrWhiteSpace(_currentPassword))
+        {
+            _passwordError = "Current password is required.";
+            return;
+        }
+        if (string.IsNullOrWhiteSpace(_newPassword) || _newPassword.Length < 8)
+        {
+            _passwordError = "New password must be at least 8 characters.";
+            return;
+        }
+        if (_newPassword != _confirmPassword)
+        {
+            _passwordError = "Passwords do not match.";
+            return;
+        }
+
+        _changingPassword = true;
+        try
+        {
+            await SettingsService.ChangePasswordAsync(_currentPassword, _newPassword);
+            _currentPassword = "";
+            _newPassword = "";
+            _confirmPassword = "";
+            _passwordPanelOpen = false;
+            _statusMessage = "Password changed successfully!";
+            _isError = false;
+        }
+        catch (Exception ex)
+        {
+            _passwordError = ex.Message;
+        }
+        finally
+        {
+            _changingPassword = false;
+        }
+    }
+
+    private void PromptRevoke(ActiveSession session)
+    {
+        _sessionToRevoke = session;
+    }
+
+    private void CancelRevoke()
+    {
+        _sessionToRevoke = null;
+    }
+
+    private async Task ConfirmRevokeAsync()
+    {
+        if (_sessionToRevoke is null) return;
+
+        _revoking = true;
+        try
+        {
+            await SettingsService.RevokeSessionAsync(_sessionToRevoke.Id);
+            _sessions.RemoveAll(s => s.Id == _sessionToRevoke.Id);
+            _statusMessage = $"Session on {_sessionToRevoke.Device} has been revoked.";
+            _isError = false;
+            _sessionToRevoke = null;
+        }
+        catch (Exception ex)
+        {
+            _statusMessage = $"Failed to revoke session: {ex.Message}";
+            _isError = true;
+        }
+        finally
+        {
+            _revoking = false;
+        }
+    }
+
+    private static string FormatLastActive(DateTime lastActive)
+    {
+        var diff = DateTime.UtcNow - lastActive;
+        if (diff.TotalMinutes < 1) return "Just now";
+        if (diff.TotalHours < 1) return $"{(int)diff.TotalMinutes}m ago";
+        if (diff.TotalDays < 1) return $"{(int)diff.TotalHours}h ago";
+        return $"{(int)diff.TotalDays}d ago";
+    }
+}
+

