@namespace sv_4139e82e566c47bdbc7e8e59a69fe4cd.Components.Pages.Settings
@using sv_4139e82e566c47bdbc7e8e59a69fe4cd.Services
@inject ISettingsService SettingsService

<div class="appearance-section">
    @if (_loading)
    {
        <div class="text-center py-4">
            <div class="spinner-border" role="status">
                <span class="visually-hidden">Loading...</span>
            </div>
        </div>
    }
    else
    {
        <h4>Appearance Settings</h4>

        @if (_statusMessage is not null)
        {
            <div class="alert alert-success alert-dismissible fade show" role="alert">
                @_statusMessage
                <button type="button" class="btn-close" @onclick="() => _statusMessage = null"></button>
            </div>
        }

        <!-- Theme Selector -->
        <div class="mb-4">
            <label class="form-label fw-bold">Theme</label>
            <div class="d-flex gap-3">
                @foreach (var theme in new[] { "Light", "Dark", "System" })
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="theme" id="@($"theme-{theme}")"
                               value="@theme" checked="@(_theme == theme)"
                               @onchange="() => _theme = theme" />
                        <label class="form-check-label" for="@($"theme-{theme}")">@theme</label>
                    </div>
                }
            </div>
        </div>

        <!-- Font Size Selector -->
        <div class="mb-4">
            <label class="form-label fw-bold">Font Size</label>
            <div class="d-flex gap-3">
                @foreach (var size in new[] { "Small", "Medium", "Large" })
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="fontSize" id="@($"fs-{size}")"
                               value="@size" checked="@(_fontSize == size)"
                               @onchange="() => _fontSize = size" />
                        <label class="form-check-label" for="@($"fs-{size}")">@size</label>
                    </div>
                }
            </div>
        </div>

        <!-- Language Dropdown -->
        <div class="mb-4">
            <label class="form-label fw-bold" for="language-select">Language</label>
            <select class="form-select" id="language-select" @bind="_language" style="max-width: 300px;">
                @foreach (var lang in _languages)
                {
                    <option value="@lang">@lang</option>
                }
            </select>
        </div>

        <!-- Compact Mode -->
        <div class="mb-4">
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" role="switch" id="compactMode"
                       checked="@_compactMode" @onchange="e => _compactMode = (bool)e.Value!" />
                <label class="form-check-label" for="compactMode">
                    <strong>Compact Mode</strong>
                    <small class="d-block text-muted">Reduce spacing and padding throughout the UI</small>
                </label>
            </div>
        </div>

        <!-- Live Preview -->
        <div class="mb-4">
            <label class="form-label fw-bold">Preview</label>
            <div class="preview-area @GetPreviewThemeClass()" style="@GetPreviewStyle()">
                <div class="preview-header">Sample Header</div>
                <p class="preview-text">
                    This is how your content will look with the selected appearance settings.
                    The theme is <strong>@_theme</strong>, font size is <strong>@_fontSize</strong>,
                    and compact mode is <strong>@(_compactMode ? "on" : "off")</strong>.
                </p>
                <div class="preview-actions">
                    <span class="preview-btn preview-btn-primary">Primary Button</span>
                    <span class="preview-btn preview-btn-secondary">Secondary Button</span>
                </div>
            </div>
        </div>

        <button class="btn btn-primary" @onclick="SaveAsync" disabled="@_saving">
            @if (_saving)
            {
                <span class="spinner-border spinner-border-sm me-1" role="status"></span>
            }
            Save
        </button>
    }
</div>

@code {
    private string _theme = "Light";
    private string _fontSize = "Medium";
    private string _language = "English";
    private bool _compactMode;
    private bool _loading = true;
    private bool _saving;
    private string? _statusMessage;

    private static readonly string[] _languages =
        ["English", "Spanish", "French", "German", "Japanese", "Chinese", "Portuguese", "Korean"];

    protected override async Task OnInitializedAsync()
    {
        _loading = true;
        var settings = await SettingsService.GetAppearanceAsync();
        _theme = settings.Theme;
        _fontSize = settings.FontSize;
        _language = settings.Language;
        _compactMode = settings.CompactMode;
        _loading = false;
    }

    private async Task SaveAsync()
    {
        _saving = true;
        _statusMessage = null;
        var updated = new AppearanceSettings(_theme, _fontSize, _language, _compactMode);
        await SettingsService.SaveAppearanceAsync(updated);
        _statusMessage = "Appearance settings saved!";
        _saving = false;
    }

    private string GetPreviewThemeClass() => _theme switch
    {
        "Dark" => "preview-dark",
        _ => "preview-light"
    };

    private string GetPreviewStyle()
    {
        var fontSize = _fontSize switch
        {
            "Small" => "0.85rem",
            "Large" => "1.15rem",
            _ => "1rem"
        };
        var padding = _compactMode ? "0.75rem" : "1.5rem";
        return $"font-size: {fontSize}; padding: {padding};";
    }
}

.appearance-section h4 {
    margin-bottom: 1.5rem;
    font-weight: 600;
}

.preview-area {
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    transition: all 0.2s ease;
}

.preview-light {
    background-color: #ffffff;
    color: #212529;
}

.preview-dark {
    background-color: #1e1e2e;
    color: #e0e0e0;
    border-color: #444;
}

.preview-header {
    font-weight: 700;
    font-size: 1.2em;
    margin-bottom: 0.75rem;
}

.preview-text {
    margin-bottom: 1rem;
    line-height: 1.5;
}

.preview-actions {
    display: flex;
    gap: 0.5rem;
}

.preview-btn {
    display: inline-block;
    padding: 0.35rem 1rem;
    border-radius: 0.375rem;
    font-size: 0.9em;
    font-weight: 500;
}

.preview-btn-primary {
    background-color: #0d6efd;
    color: #fff;
}

.preview-dark .preview-btn-primary {
    background-color: #4a9eff;
}

.preview-btn-secondary {
    background-color: #e9ecef;
    color: #495057;
}

.preview-dark .preview-btn-secondary {
    background-color: #3a3a4a;
    color: #ccc;
}

